import{bQ as e,aL as a,u as r,G as n}from"./chunks/framework.C1gZXFVa.js";const c=JSON.parse('{"title":"交易规则","description":"先明确开平仓语义、保证金模式、价格依据和费用口径，再允许订单进入撮合。","frontmatter":{"title":"交易规则","description":"先明确开平仓语义、保证金模式、价格依据和费用口径，再允许订单进入撮合。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX,合约手册,保证金,强平清算"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/0803"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/0803"}],["meta",{"property":"og:title","content":"交易规则 · TGEX"}],["meta",{"property":"og:description","content":"先明确开平仓语义、保证金模式、价格依据和费用口径，再允许订单进入撮合。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"交易规则 · TGEX"}],["meta",{"name":"twitter:description","content":"先明确开平仓语义、保证金模式、价格依据和费用口径，再允许订单进入撮合。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"交易规则\\",\\"description\\":\\"先明确开平仓语义、保证金模式、价格依据和费用口径，再允许订单进入撮合。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX,合约手册,保证金,强平清算\\",\\"url\\":\\"https://tgex.net/pages/0803\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/0803\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/0803.md","filePath":"08.合约手册/03.交易规则.md"}'),o={name:"pages/0803.md"};function d(i,t,p,s,h,l){return a(),r("div",null,[...t[0]||(t[0]=[n('<div class="doc-eyebrow">合约手册 / TGEX KNOWLEDGE BASE</div><h1 id="交易规则" tabindex="-1">交易规则 <a class="header-anchor" href="#交易规则" aria-label="Permalink to &quot;交易规则&quot;">​</a></h1><div class="doc-lead">先确定订单是否合法，再占用保证金或可平数量。合法规则是委托校验的输入；对象建模见[核心设计](/pages/0804)；谁执行见[系统架构](/pages/0802)。</div><p>规则检查发生在真正改热钱包 / 持仓之前。不合法应拒单，而不是带着错误参数进入可成交状态。平台开仓校验落点见<a href="/pages/080501">开仓主流程</a>。</p><h2 id="direction" tabindex="-1">开平仓与方向 <a class="header-anchor" href="#direction" aria-label="Permalink to &quot;开平仓与方向 {#direction}&quot;">​</a></h2><p>买卖方向与开平仓用途不是同一个维度：</p><table tabindex="0"><thead><tr><th>维度</th><th>例子</th></tr></thead><tbody><tr><td>交易方向</td><td>买 / 卖（挂到订单簿的一侧）</td></tr><tr><td>开平用途</td><td>开多、开空、平多、平空</td></tr></tbody></table><p>买入可以开多，也可以用于平空。平仓量必须落在<strong>可平数量</strong>内，防止多笔平仓单重复使用同一持仓。</p><p><strong>本册流程覆盖</strong>：平台永续 · 限价开仓 / 平仓。市价、止盈止损、计划委托等能力以产品启用为准，逐步时序未全部单开。</p><h2 id="margin" tabindex="-1">杠杆与保证金模式 <a class="header-anchor" href="#margin" aria-label="Permalink to &quot;杠杆与保证金模式 {#margin}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>含义</th></tr></thead><tbody><tr><td>杠杆</td><td>放大名义敞口的倍数；不改变「价格涨跌 1%」对同等名义的绝对波动，但改变保证金需求</td></tr><tr><td>逐仓</td><td>保证金与风险按仓位隔离（实现细节按产品）</td></tr><tr><td>全仓</td><td>同一结算币权益共享风险（实现细节按产品）</td></tr></tbody></table><p>教学示例（与<a href="/pages/0801#complete">业务概述 · 案例</a>同一组数）：名义 600 USDT、杠杆 10 倍时，简单初始保证金约 60 USDT，<strong>尚未</strong>计手续费、资金费与风险限额档位。实际占用以撮合受理结果为准。</p><p>开仓前至少要能回答：</p><ol><li>产品是否可交易、涨跌幅是否允许？</li><li>杠杆是否超过该产品 / 用户档位上限？</li><li>可用保证金是否覆盖初始占用（含规则要求的费用缓冲）？</li><li>若为平仓：可平数量是否足够？</li></ol><h2 id="fees" tabindex="-1">价格、限额与费用 <a class="header-anchor" href="#fees" aria-label="Permalink to &quot;价格、限额与费用 {#fees}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>价格</th><th>常见用途</th></tr></thead><tbody><tr><td>最新成交价</td><td>盘口成交事实、部分展示</td></tr><tr><td>指数价</td><td>由外部现货等组成的参考</td></tr><tr><td>标记价</td><td>浮盈展示与强平扫描等风险口径（以产品为准）</td></tr></tbody></table><p>用于盈亏展示、强平和成交的价格依据必须分开写清，不能「一个最新价打天下」。</p><p>手续费需要说明：费率来源、收取币种、收取时机（通常成交时）、舍入。<br> 资金费：仅当产品启用；是多空之间按规则的定期结算，<strong>不能</strong>等同借币利息，也不能默认所有合约都收。</p><p>风险限额 / 仓位档位会提高维持要求或限制开仓规模；写规则时要能指向「档位从哪来」，避免只写「杠杆越高越危险」这种空话。</p><p>同组：<a href="/pages/0801">业务概述</a> · <a href="/pages/0802">系统架构</a> · <a href="/pages/0804">核心设计</a> · <a href="/pages/080501">开仓主流程</a></p>',20)])])}const m=e(o,[["render",d]]);export{c as __pageData,m as default};
